<?php
session_start();
function clean($v,$max=3000){$v=trim((string)$v);$v=str_replace(["\r","\n"],' ',$v);return htmlspecialchars(substr($v,0,$max),ENT_QUOTES,'UTF-8');}
function valid_email($e){return filter_var($e,FILTER_VALIDATE_EMAIL)&&!preg_match('/[\r\n]/',$e);} function fail($msg){$_SESSION['form_error']=$msg;header('Location:/forms/error.php');exit;} function ok(){header('Location:/forms/success.php');exit;}
function guard(){if(!empty($_POST['website'])) fail('Spam protection rejected this submission.'); $t=(int)($_POST['form_started_at']??0); if($t && (time()*1000-$t)<1200) fail('Please try again.'); $last=$_SESSION['last_submit']??0; if(time()-$last<20) fail('Please wait before submitting again.'); $_SESSION['last_submit']=time();}
function send_basic_mail($subject,$fields,$reply=''){ $cfg=file_exists(__DIR__.'/../config/mail-config.php')?require __DIR__.'/../config/mail-config.php':require __DIR__.'/../config/mail-config.example.php'; $to=$cfg['MAIL_TO']; $from=$cfg['MAIL_FROM']; $body="Trinetra Fleet Solutions enquiry\n\n"; foreach($fields as $k=>$v){$body.=clean($k,80).": ".clean($v)."\n";} $headers="From: {$from}\r\nReply-To: ".($reply?:$from)."\r\nContent-Type: text/plain; charset=UTF-8"; return @mail($to,$subject,$body,$headers); }
function ack($email,$name){ if(!valid_email($email)) return; $cfg=file_exists(__DIR__.'/../config/mail-config.php')?require __DIR__.'/../config/mail-config.php':require __DIR__.'/../config/mail-config.example.php'; @mail($email,'Enquiry received - Trinetra Fleet Solutions',"Dear {$name},\n\nThank you for contacting Trinetra Fleet Solutions. Our team will review your enquiry and respond shortly.\n\nRegards,\nTrinetra Fleet Solutions","From: {$cfg['MAIL_FROM']}\r\nContent-Type: text/plain; charset=UTF-8");}
function handle_file(){ if(empty($_FILES['cv'])||$_FILES['cv']['error']===UPLOAD_ERR_NO_FILE) return 'No CV attached'; if($_FILES['cv']['error']!==UPLOAD_ERR_OK) fail('CV upload failed.'); if($_FILES['cv']['size']>2*1024*1024) fail('CV file is too large.'); $name=$_FILES['cv']['name']; $ext=strtolower(pathinfo($name,PATHINFO_EXTENSION)); if(!in_array($ext,['pdf','doc','docx'],true)) fail('Only PDF, DOC and DOCX files are accepted.'); return 'CV received: '.basename($name); }
